package com.queuecraft.ui;
import com.queuecraft.concurrent.*; import com.queuecraft.engine.*; import com.queuecraft.model.*; import com.queuecraft.service.*; import javax.swing.*; import javax.swing.border.EmptyBorder; import java.awt.*;
public final class QueueCraftFrame extends JFrame {
 private final SimulationEngine engine=new SimulationEngine(); private final SimulationRunner runner=new SimulationRunner(engine,this::refresh); private final DefaultListModel<String> counterModel=new DefaultListModel<>(); private final JList<String> counterList=new JList<>(counterModel); private final JTextArea queues=new JTextArea(),log=new JTextArea(); private final JLabel summary=new JLabel(),stats=new JLabel(); private final JComboBox<ServiceType> service=new JComboBox<>(ServiceType.values()); private final JSpinner batch=new JSpinner(new SpinnerNumberModel(6,1,100,1));
 public QueueCraftFrame(){super("QueueCraft — Campus Service Queue & Bottleneck Simulator");setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);setMinimumSize(new Dimension(900,620));setSize(1100,720);setLocationRelativeTo(null);build();seed();refresh();addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosing(java.awt.event.WindowEvent e){runner.close();dispose();}});}
 private void build(){JPanel root=new JPanel(new BorderLayout(12,12));root.setBorder(new EmptyBorder(18,18,18,18));root.setBackground(new Color(244,247,251));setContentPane(root);JLabel title=new JLabel("QueueCraft"),subtitle=new JLabel("Campus service queues, made visible. One simulation tick = 0.4 seconds of real time.");title.setFont(new Font("Segoe UI",Font.BOLD,26));subtitle.setForeground(new Color(85,100,120));JPanel head=new JPanel(new GridLayout(2,1,2,2));head.setOpaque(false);head.add(title);head.add(subtitle);root.add(head,BorderLayout.NORTH);
 JPanel body=new JPanel(new GridLayout(1,2,12,0));body.setOpaque(false);root.add(body,BorderLayout.CENTER);JPanel left=card("Service counters");left.setLayout(new BorderLayout(8,8));counterList.setFont(new Font("Segoe UI",0,14));left.add(new JScrollPane(counterList),BorderLayout.CENTER);JPanel controls=new JPanel(new GridLayout(0,1,5,5));controls.setOpaque(false);JButton add=new JButton("Add counter…"),toggle=new JButton("Enable / disable selected"),remove=new JButton("Remove selected");controls.add(add);controls.add(toggle);controls.add(remove);left.add(controls,BorderLayout.SOUTH);
 add.addActionListener(e->addCounter());toggle.addActionListener(e->{String n=selectedName();if(n!=null)try{ServiceCounter c=engine.getCounters().stream().filter(x->x.getName().equals(n)).findFirst().orElseThrow();engine.setCounterEnabled(n,!c.isEnabled());refresh();}catch(Exception ex){error(ex);}});remove.addActionListener(e->{String n=selectedName();if(n!=null)try{engine.removeCounter(n);refresh();}catch(Exception ex){error(ex);}});
 JPanel right=card("Queue & activity");right.setLayout(new BorderLayout(8,8));queues.setEditable(false);queues.setFont(new Font("Consolas",0,12));log.setEditable(false);log.setFont(new Font("Consolas",0,12));JSplitPane queueSplit=new JSplitPane(JSplitPane.VERTICAL_SPLIT,new JScrollPane(queues),new JScrollPane(log));queueSplit.setResizeWeight(0.42);right.add(queueSplit,BorderLayout.CENTER);body.add(left);body.add(right);JPanel south=new JPanel(new BorderLayout(8,8));south.setOpaque(false);JPanel top=new JPanel(new GridLayout(2,1,3,3));top.setOpaque(false);summary.setFont(new Font("Segoe UI",Font.BOLD,14));stats.setFont(new Font("Segoe UI",0,13));top.add(summary);top.add(stats);south.add(top,BorderLayout.NORTH);JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.setOpaque(false);JButton run=new JButton("Start / resume"),pause=new JButton("Pause"),reset=new JButton("Reset"),generate=new JButton("Generate batch");actions.add(run);actions.add(pause);actions.add(reset);actions.add(service);actions.add(batch);actions.add(generate);south.add(actions,BorderLayout.SOUTH);root.add(south,BorderLayout.SOUTH);run.addActionListener(e->runner.resume());pause.addActionListener(e->runner.pause());reset.addActionListener(e->runner.reset());generate.addActionListener(e->{try{engine.generateBatch((ServiceType)service.getSelectedItem(),(Integer)batch.getValue());refresh();}catch(Exception ex){error(ex);}});}
 private JPanel card(String name){JPanel p=new JPanel();p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createTitledBorder(name),new EmptyBorder(8,8,8,8)));p.setBackground(Color.WHITE);return p;}
 private void seed(){try{engine.addCounter(new ServiceCounter("Canteen A",ServiceType.CANTEEN,3));engine.addCounter(new ServiceCounter("Canteen B",ServiceType.CANTEEN,5));engine.addCounter(new ServiceCounter("Library Desk",ServiceType.LIBRARY,4));engine.addCounter(new ServiceCounter("Student Office",ServiceType.STUDENT_OFFICE,6));engine.addCounter(new ServiceCounter("IT Help Desk",ServiceType.IT_HELP,3));engine.generateBatch(ServiceType.CANTEEN,10);engine.generateBatch(ServiceType.LIBRARY,4);}catch(Exception e){error(e);}}
 private void addCounter(){JTextField name=new JTextField();JComboBox<ServiceType> type=new JComboBox<>(ServiceType.values());JSpinner ticks=new JSpinner(new SpinnerNumberModel(4,1,100,1));JPanel p=new JPanel(new GridLayout(0,2,6,6));p.add(new JLabel("Name"));p.add(name);p.add(new JLabel("Service"));p.add(type);p.add(new JLabel("Duration (ticks)"));p.add(ticks);if(JOptionPane.showConfirmDialog(this,p,"Add service counter",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{ServiceCounter c=CounterValidator.create(name.getText(),(ServiceType)type.getSelectedItem(),(Integer)ticks.getValue(),engine.getCounters());engine.addCounter(c);refresh();}catch(Exception ex){error(ex);}}
 private String selectedName(){String s=counterList.getSelectedValue();return s==null?null:s.substring(0,s.indexOf("  |"));}
 private void refresh(){SimulationStats s=engine.stats();summary.setText("Tick "+engine.getTick()+" · "+(engine.isPaused()?"Paused":"Running")+" · "+s.generated()+" customers generated");stats.setText(String.format("Waiting %d   Serving %d   Completed %d   Avg wait %.1f ticks   Avg service %.1f ticks   Max queue %d",s.waiting(),s.serving(),s.completed(),s.averageWait(),s.averageService(),s.maxQueue()));counterModel.clear();for(ServiceCounter c:engine.getCounters()){String active=c.getCurrentCustomer()==null?"None":c.getCurrentCustomer().getDisplayName()+" ("+c.getRemainingTicks()+" ticks)";counterModel.addElement(c.getName()+"  |  "+(c.isEnabled()?"ON":"OFF")+" · "+c.getServiceType()+" · active: "+active+" · waiting: "+c.getWaitingCount()+" · done: "+c.getCompletedCount());}StringBuilder q=new StringBuilder();for(ServiceCounter c:engine.getCounters()){q.append(c.getName()).append(": ");if(c.getCurrentCustomer()==null)q.append("idle");else q.append("serving ").append(c.getCurrentCustomer().getDisplayName()).append(" (").append(c.getRemainingTicks()).append(" ticks left)");q.append(System.lineSeparator()).append("  Waiting: ");if(c.getWaitingCount()==0)q.append("none");else{boolean first=true;for(Customer customer:c.getWaiting()){if(!first)q.append(", ");q.append(customer.getDisplayName());first=false;}}q.append(System.lineSeparator());}queues.setText(q.toString());StringBuilder b=new StringBuilder();for(String event:engine.getEvents())b.append(event).append('\n');log.setText(b.toString());log.setCaretPosition(log.getDocument().getLength());}
 private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"QueueCraft",JOptionPane.WARNING_MESSAGE);}
}
